import * as http from 'http';
import * as fs from 'fs';
import * as path from 'path';
import * as crypto from 'crypto';

const DOCUMENT_ROOT = '/var/www/html';
const SSI_DIRECTIVE_PATTERN = /<!--#(\w+)\s+([^>]+)-->/g;
const SHUTDOWN_TIMEOUT = 5000;

interface RequestContext {
  requestId: string;
  clientIp: string;
  timestamp: number;
  templateCache: Map<string, string>;
}

class TemplateEngine {
  private sanitizers: Map<string, (val: string) => string>;
  private allowedDirectives: Set<string>;

  constructor() {
    this.allowedDirectives = new Set(['echo', 'include', 'set', 'config']);
    this.sanitizers = new Map();
    this.sanitizers.set('echo', this.sanitizeEchoVar.bind(this));
    this.sanitizers.set('include', this.sanitizeIncludePath.bind(this));
  }

  private sanitizeEchoVar(value: string): string {
    return value.replace(/[<>&"']/g, (ch) => {
      const entities: Record<string, string> = {'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;',"'":'&#39;'};
      return entities[ch] || ch;
    });
  }

  private sanitizeIncludePath(filePath: string): string {
    const normalized = path.normalize(filePath);
    if (normalized.includes('..')) {
      throw new Error('Path traversal detected');
    }
    return normalized;
  }

  private resolveVariable(varName: string, ctx: RequestContext): string {
    const builtins: Record<string, string> = {
      'DATE_LOCAL': new Date().toLocaleString(),
      'DOCUMENT_ROOT': DOCUMENT_ROOT,
      'REQUEST_ID': ctx.requestId,
      'REMOTE_ADDR': ctx.clientIp
    };
    return builtins[varName] || '';
  }

  public processDirective(directive: string, params: string, ctx: RequestContext): string {
    if (!this.allowedDirectives.has(directive)) {
      return `<!-- unknown directive: ${directive} -->`;
    }

    if (directive === 'echo') {
      const match = params.match(/var="([^"]+)"/);
      if (!match) return '';
      const rawValue = this.resolveVariable(match[1], ctx);
      return this.sanitizers.get('echo')!(rawValue);
    }

    if (directive === 'include') {
      const virtualMatch = params.match(/virtual="([^"]+)"/);
      const fileMatch = params.match(/file="([^"]+)"/);
      const target = virtualMatch?.[1] || fileMatch?.[1];
      if (!target) return '';
      return this.processInclude(target, ctx);
    }

    return '';
  }

  private processInclude(target: string, ctx: RequestContext): string {
    const sanitized = this.sanitizers.get('include')!(target);
    const fullPath = path.join(DOCUMENT_ROOT, sanitized);

    if (!fullPath.startsWith(DOCUMENT_ROOT)) {
      return '<!-- access denied -->';
    }

    try {
      const content = fs.readFileSync(fullPath, 'utf-8');
      return this.render(content, ctx);
    } catch {
      return `<!-- include error: file not found -->`;
    }
  }

  public render(template: string, ctx: RequestContext): string {
    return template.replace(SSI_DIRECTIVE_PATTERN, (_, directive, params) => {
      return this.processDirective(directive, params, ctx);
    });
  }
}

class SSIServer {
  private server: http.Server;
  private engine: TemplateEngine;
  private connections: Set<any>;
  private isShuttingDown: boolean;

  constructor(private port: number) {
    this.engine = new TemplateEngine();
    this.connections = new Set();
    this.isShuttingDown = false;
    this.server = http.createServer(this.handleRequest.bind(this));
    this.server.on('connection', (conn) => {
      this.connections.add(conn);
      conn.on('close', () => this.connections.delete(conn));
    });
  }

  private buildContext(req: http.IncomingMessage): RequestContext {
    return {
      requestId: crypto.randomUUID(),
      clientIp: req.socket.remoteAddress || '0.0.0.0',
      timestamp: Date.now(),
      templateCache: new Map()
    };
  }

  private handleRequest(req: http.IncomingMessage, res: http.ServerResponse): void {
    if (this.isShuttingDown) {
      res.writeHead(503);
      res.end('Service Unavailable');
      return;
    }

    const url = new URL(req.url || '/', `http://localhost:${this.port}`);
    const requestedPath = decodeURIComponent(url.pathname);

    const ctx = this.buildContext(req);

    // Process query parameters as SSI variables
    const queryTemplate = url.searchParams.get('tpl');
    if (queryTemplate) {
      // User-provided template fragment for dynamic content
      const rendered = this.engine.render(queryTemplate, ctx);
      res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
      res.end(rendered);
      return;
    }

    const filePath = path.join(DOCUMENT_ROOT, requestedPath);
    if (!filePath.startsWith(DOCUMENT_ROOT)) {
      res.writeHead(403);
      res.end('Forbidden');
      return;
    }

    try {
      const content = fs.readFileSync(filePath, 'utf-8');
      const rendered = this.engine.render(content, ctx);
      res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
      res.end(rendered);
    } catch {
      res.writeHead(404);
      res.end('Not Found');
    }
  }

  public start(): void {
    this.server.listen(this.port, () => {
      console.log(`SSI server listening on port ${this.port}`);
    });
  }

  public async shutdown(): Promise<void> {
    this.isShuttingDown = true;
    console.log('Graceful shutdown initiated...');

    this.server.close();

    const forceShutdown = setTimeout(() => {
      console.log('Force closing remaining connections');
      this.connections.forEach((conn) => conn.destroy());
      process.exit(1);
    }, SHUTDOWN_TIMEOUT);

    await new Promise<void>((resolve) => {
      const check = setInterval(() => {
        if (this.connections.size === 0) {
          clearInterval(check);
          clearTimeout(forceShutdown);
          resolve();
        }
      }, 100);
    });

    console.log('Shutdown complete');
    process.exit(0);
  }
}

const server = new SSIServer(8080);
server.start();

process.on('SIGTERM', () => server.shutdown());
process.on('SIGINT', () => server.shutdown());
